public class ImageView : Control {
 public Bitmap Image;public string Caption="Choose a picture to preview your design";
 public ImageView(){DoubleBuffered=true;BackColor=Color.FromArgb(14,22,33);}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;for(int y=0;y<Height;y+=16)for(int x=0;x<Width;x+=16)using(var b=new SolidBrush((x/16+y/16)%2==0?Color.FromArgb(24,34,46):Color.FromArgb(29,40,53)))g.FillRectangle(b,x,y,16,16);if(Image==null){TextRenderer.DrawText(g,Caption,Font,ClientRectangle,Color.LightSlateGray,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.WordBreak);return;}float scale=Math.Min((Width-20f)/Image.Width,(Height-20f)/Image.Height);int w=Math.Max(1,(int)(Image.Width*scale)),h=Math.Max(1,(int)(Image.Height*scale));g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.DrawImage(Image,new Rectangle((Width-w)/2,(Height-h)/2,w,h));}
 public void Set(Bitmap image){if(Image!=null)Image.Dispose();Image=image;Invalidate();}
 protected override void Dispose(bool disposing){if(disposing&&Image!=null){Image.Dispose();Image=null;}base.Dispose(disposing);}
}
public class MenuView : Control {
 public Dictionary<string,Bitmap> Images=new Dictionary<string,Bitmap>();public Dictionary<string,Rectangle> Hotspots=new Dictionary<string,Rectangle>();public Action<string> Pick;public string SelectedName;public Bitmap Pending;
 public MenuView(){DoubleBuffered=true;Cursor=Cursors.Hand;MouseClick+=delegate(object s,MouseEventArgs e){foreach(var p in Hotspots)if(p.Value.Contains(e.Location)){if(Pick!=null)Pick(p.Key);break;}};}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;using(var b=new LinearGradientBrush(ClientRectangle,Color.FromArgb(32,79,120),Color.FromArgb(11,26,43),90f))g.FillRectangle(b,ClientRectangle);Hotspots.Clear();int w=Width,h=Height;Draw(g,"GJ_logo_001.png",new Rectangle(w/5,8,w*3/5,h/5));Draw(g,"GJ_garageBtn_001.png",new Rectangle(w/4-30,h/3,60,60));Draw(g,"GJ_playBtn_001.png",new Rectangle(w/2-42,h/3-10,84,84));Draw(g,"GJ_creatorBtn_001.png",new Rectangle(w*3/4-30,h/3,60,60));Draw(g,"GJ_profileButton_001.png",new Rectangle(20,h/2,48,48));Draw(g,"GJ_searchBtn_001.png",new Rectangle(w-70,h/2,48,48));string[] faces={"difficulty_01_btn_001.png","difficulty_03_btn_001.png","difficulty_08_btn_001.png","difficulty_10_btn_001.png"};for(int i=0;i<faces.Length;i++)Draw(g,faces[i],new Rectangle(w/2-120+i*62,h-66,45,45));TextRenderer.DrawText(g,"Illustrative preview - click an item to customize it",Font,new Rectangle(0,h-20,w,20),Color.LightGray,TextFormatFlags.HorizontalCenter);}
 void Draw(Graphics g,string key,Rectangle r){Hotspots[key]=r;Bitmap im;if(key==SelectedName&&Pending!=null)im=Pending;else Images.TryGetValue(key,out im);if(im!=null){float s=Math.Min((float)r.Width/im.Width,(float)r.Height/im.Height);int w=(int)(im.Width*s),h=(int)(im.Height*s);g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.DrawImage(im,new Rectangle(r.X+(r.Width-w)/2,r.Y+(r.Height-h)/2,w,h));}if(key==SelectedName)using(var p=new Pen(Color.FromArgb(93,241,197),2))g.DrawRectangle(p,r);}
 public void Clear(){foreach(var im in Images.Values)im.Dispose();Images.Clear();}
 protected override void Dispose(bool disposing){if(disposing)Clear();base.Dispose(disposing);}
}
