 static ComboBox Combo(){return new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,BackColor=Card,ForeColor=Ink};}static TrackBar Slider(int min,int max,int value){return new TrackBar{Minimum=min,Maximum=max,Value=value,TickStyle=TickStyle.None};}
